-- VITARA: initial schema, ownership policies, and reproducible recipe seeds.
-- Apply once with Supabase CLI migrations or the SQL editor, as the database owner.
-- Nutrition: recipe calculations from USDA SR Legacy (April 2018), not laboratory
-- measurements of these mixed dishes. See nutrition_source_json on every food.
-- GI values are explicitly unvalidated planning estimates. GL inherits that uncertainty.

begin;

create schema if not exists extensions;
create extension if not exists "uuid-ossp" with schema extensions;
create extension if not exists pgcrypto with schema extensions;

create type public.chronotype as enum
  ('early_bird', 'intermediate', 'night_owl', 'night_shift');
create type public.dietary_pattern as enum
  ('lacto_vegetarian', 'vegan', 'eggetarian', 'halal', 'omnivore');
create type public.glycemic_tier as enum ('low', 'medium', 'high');

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text not null check (length(btrim(full_name)) between 1 and 200),
  city text not null check (length(btrim(city)) between 1 and 200),
  latitude double precision not null check (latitude between -90 and 90),
  longitude double precision not null check (longitude between -180 and 180),
  timezone text not null,
  cultural_heritages text[] not null
    check (cardinality(cultural_heritages) between 1 and 4
      and array_position(cultural_heritages, null) is null
      and cultural_heritages <@ array[
        'south_asian','west_african','middle_eastern','latin_american']::text[]),
  dietary_pattern public.dietary_pattern not null,
  metabolic_flags text[] not null default '{}'::text[]
    check (cardinality(metabolic_flags) <= 30
      and array_position(metabolic_flags, null) is null),
  ramadan_mode boolean not null default false,
  wake_time time without time zone not null,
  sleep_time time without time zone not null,
  chronotype public.chronotype not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint profiles_distinct_wake_sleep check (wake_time <> sleep_time),
  constraint profiles_clock_bounds check (
    wake_time < time '24:00' and sleep_time < time '24:00')
);

comment on column public.profiles.cultural_heritages is
  'Canonical cuisine keys. These are user-selected food preferences, not inferred ethnicity.';
comment on column public.profiles.metabolic_flags is
  'User-provided context; recognized ranking flags: t2d_family_history, pcos. Not a diagnosis.';
comment on column public.profiles.sleep_time is
  'Sleep following wake_time: a smaller clock time means the following local calendar day.';

create table public.cultural_foods (
  id uuid primary key default gen_random_uuid(),
  dish_name text not null unique check (length(btrim(dish_name)) between 1 and 200),
  culture text not null check (culture in
    ('south_asian','west_african','middle_eastern','latin_american')),
  meal_slot text[] not null check (
    cardinality(meal_slot) between 1 and 4
    and array_position(meal_slot, null) is null
    and meal_slot <@ array['breakfast','lunch','dinner','snack']::text[]),
  dietary_pattern public.dietary_pattern not null,
  dietary_tags text[] not null check (
    cardinality(dietary_tags) between 1 and 8
    and array_position(dietary_tags, null) is null
    and dietary_tags <@ array['lacto_vegetarian','vegan','vegetarian',
      'eggetarian','halal','non_veg','omnivore']::text[]),
  serving_description text not null check (length(btrim(serving_description)) > 0),
  serving_grams numeric(8,2) not null check (serving_grams > 0 and serving_grams <= 10000),
  calories numeric(8,2) not null check (calories >= 0 and calories <= 10000),
  protein_g numeric(8,2) not null check (protein_g >= 0 and protein_g <= serving_grams),
  carbs_g numeric(8,2) not null check (carbs_g >= 0 and carbs_g <= serving_grams),
  fiber_g numeric(8,2) not null check (fiber_g >= 0 and fiber_g <= carbs_g),
  fat_g numeric(8,2) not null check (fat_g >= 0 and fat_g <= serving_grams),
  gi_estimate numeric(5,2) not null check (gi_estimate >= 0 and gi_estimate <= 100),
  gl_score numeric(8,2) generated always as
    (round(gi_estimate * (carbs_g - fiber_g) / 100, 2)) stored,
  glycemic_tier public.glycemic_tier generated always as (
    case
      when round(gi_estimate * (carbs_g - fiber_g) / 100, 2) <= 10
        then 'low'::public.glycemic_tier
      when round(gi_estimate * (carbs_g - fiber_g) / 100, 2) < 20
        then 'medium'::public.glycemic_tier
      else 'high'::public.glycemic_tier
    end
  ) stored,
  metabolic_hack_tip text not null check (length(btrim(metabolic_hack_tip)) > 0),
  swap_group_tag text not null check (length(btrim(swap_group_tag)) > 0),
  nutrition_source_json jsonb not null check (
    jsonb_typeof(nutrition_source_json) = 'object'
    and nutrition_source_json ?& array[
      'source','source_url','method','ingredients','gi_method']),
  created_at timestamptz not null default now(),
  constraint foods_macro_mass check (protein_g + carbs_g + fat_g <= serving_grams + 1),
  constraint foods_compatible_classification check (dietary_pattern::text = any(dietary_tags))
);

comment on column public.cultural_foods.dietary_pattern is
  'Recipe classification. Filter user compatibility using dietary_tags, not enum equality.';
comment on column public.cultural_foods.gi_estimate is
  'Unvalidated mixed-recipe planning estimate; not a measured GI or personal glucose prediction.';
comment on column public.cultural_foods.gl_score is
  'Estimated GL per stated portion: GI * (USDA total carbohydrate minus fiber) / 100.';
comment on column public.cultural_foods.glycemic_tier is
  'GL tier, not GI tier: low <= 10; medium > 10 and < 20; high >= 20.';
comment on column public.cultural_foods.nutrition_source_json is
  'Reproducible ingredient weights, official FDC IDs and per-100g macros. Recipe/calorie/GL estimates.';

create table public.workouts (
  id uuid primary key default gen_random_uuid(),
  title text not null unique check (length(btrim(title)) between 1 and 200),
  environment text not null check (environment in ('indoor','outdoor')),
  intensity text not null check (intensity in ('low','moderate','vigorous')),
  duration_mins integer not null check (duration_mins between 1 and 180),
  metabolic_benefit text not null check (length(btrim(metabolic_benefit)) > 0),
  swap_pair_id uuid not null unique,
  created_at timestamptz not null default now(),
  constraint workouts_distinct_pair check (id <> swap_pair_id),
  constraint workouts_swap_pair_fk foreign key (swap_pair_id)
    references public.workouts(id) deferrable initially deferred
);

create table public.daily_plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  plan_date date not null,
  weather_summary_json jsonb not null check (jsonb_typeof(weather_summary_json) = 'object'),
  is_indoor_override boolean not null,
  schedule_blocks_json jsonb not null check (
    jsonb_typeof(schedule_blocks_json) = 'array'
    and jsonb_array_length(schedule_blocks_json) between 1 and 40),
  adherence_score integer check (adherence_score between 0 and 100),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint daily_plans_user_date_unique unique(user_id, plan_date)
);

comment on column public.daily_plans.plan_date is
  'Local wake-cycle date normally; fasting civil date in Ramadan mode. Events can cross midnight. See weather_summary_json.schedule_metadata.date_basis.';
comment on column public.daily_plans.adherence_score is
  'Null until adherence is measured; integer percentage 0..100 thereafter.';

create index cultural_foods_culture_idx on public.cultural_foods(culture);
create index cultural_foods_dietary_tags_idx on public.cultural_foods using gin(dietary_tags);
create index cultural_foods_meal_slot_idx on public.cultural_foods using gin(meal_slot);
create index cultural_foods_metabolic_rank_idx
  on public.cultural_foods(glycemic_tier, fiber_g desc, gl_score);
create index workouts_environment_intensity_idx
  on public.workouts(environment, intensity, duration_mins);
-- The unique (user_id, plan_date) index also supports ownership checks and history queries.

create function public.validate_profile_timezone()
returns trigger language plpgsql set search_path = '' as $$
begin
  if not (
    (new.timezone = 'UTC' or new.timezone ~ '^[A-Za-z_]+(/[A-Za-z0-9_+.-]+)+$')
    and new.timezone not like 'posix/%'
    and new.timezone not like 'right/%'
    and exists (select 1 from pg_catalog.pg_timezone_names where name = new.timezone)
  ) then
    raise exception using errcode = '23514', message = 'timezone must be a valid IANA zone or UTC';
  end if;
  return new;
end;
$$;

create trigger profiles_validate_timezone
before insert or update of timezone on public.profiles
for each row execute function public.validate_profile_timezone();

create function public.set_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at := pg_catalog.now();
  return new;
end;
$$;

create trigger profiles_set_updated_at before update on public.profiles
for each row execute function public.set_updated_at();
create trigger daily_plans_set_updated_at before update on public.daily_plans
for each row execute function public.set_updated_at();

create function public.validate_workout_pair()
returns trigger language plpgsql set search_path = '' as $$
declare
  actual public.workouts%rowtype;
  partner public.workouts%rowtype;
begin
  -- Read final transaction state: multiple pair edits may have queued this trigger.
  select * into actual from public.workouts where id = new.id;
  if not found then return null; end if;
  select * into partner from public.workouts where id = actual.swap_pair_id;
  if not found
     or partner.swap_pair_id <> actual.id
     or partner.environment = actual.environment
     or partner.duration_mins <> actual.duration_mins
     or partner.intensity <> actual.intensity then
    raise exception using errcode = '23514',
      message = 'Workout pairs must be reciprocal, opposite-environment, and match duration/intensity';
  end if;
  return null;
end;
$$;

create constraint trigger workouts_validate_pair
after insert or update on public.workouts
deferrable initially deferred for each row
execute function public.validate_workout_pair();

revoke all on function public.validate_profile_timezone() from public, anon, authenticated;
revoke all on function public.set_updated_at() from public, anon, authenticated;
revoke all on function public.validate_workout_pair() from public, anon, authenticated;

alter table public.profiles enable row level security;
alter table public.cultural_foods enable row level security;
alter table public.workouts enable row level security;
alter table public.daily_plans enable row level security;

-- Remove inherited Supabase default grants; RLS and privileges are both explicit.
revoke all on table public.profiles, public.cultural_foods, public.workouts,
  public.daily_plans from public, anon, authenticated;
grant usage on schema public to authenticated, service_role;
grant select, insert, update, delete on public.profiles, public.daily_plans to authenticated;
grant select on public.cultural_foods, public.workouts to authenticated;
grant all on public.profiles, public.daily_plans, public.cultural_foods,
  public.workouts to service_role;
grant usage on type public.chronotype, public.dietary_pattern, public.glycemic_tier
  to authenticated, service_role;

create policy profiles_select_own on public.profiles for select to authenticated
  using ((select auth.uid()) = id);
create policy profiles_insert_own on public.profiles for insert to authenticated
  with check ((select auth.uid()) = id);
create policy profiles_update_own on public.profiles for update to authenticated
  using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
create policy profiles_delete_own on public.profiles for delete to authenticated
  using ((select auth.uid()) = id);

create policy daily_plans_select_own on public.daily_plans for select to authenticated
  using ((select auth.uid()) = user_id);
create policy daily_plans_insert_own on public.daily_plans for insert to authenticated
  with check ((select auth.uid()) = user_id);
create policy daily_plans_update_own on public.daily_plans for update to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy daily_plans_delete_own on public.daily_plans for delete to authenticated
  using ((select auth.uid()) = user_id);

create policy cultural_foods_read_authenticated on public.cultural_foods
  for select to authenticated using ((select auth.uid()) is not null);
create policy workouts_read_authenticated on public.workouts
  for select to authenticated using ((select auth.uid()) is not null);

-- All 20 recipes carry their complete reproducible ingredient specification.
-- The halal tag on meat recipes is conditional on the explicitly stated certified
-- halal sourcing requirement; it is not a certification from the USDA database.
