) values
  ('10000000-0000-4000-8000-000000000001', 'Dal palak', 'south_asian', array['breakfast','lunch','dinner']::text[], 'vegan', array['vegan','vegetarian','lacto_vegetarian','eggetarian','halal','omnivore']::text[], 'One 329 g portion, prepared exactly from the ingredient weights in nutrition_source_json; sides are included only when named.', 329, 294.82, 19.55, 44.04, 17.13, 6.23, 32, 'Keep the lentils and spinach; pair with a modest portion of whole grain rather than adding a large rice serving.', 'legume_main', '{"source":"USDA FoodData Central, SR Legacy, April 2018","source_url":"https://fdc.nal.usda.gov/fdc-datasets/FoodData_Central_sr_legacy_food_json_2018-04.zip","method":"Recipe estimate: sum(ingredient grams * reference nutrient per 100 g / 100), rounded to 2 decimals. Total carbohydrate includes fiber; available carbohydrate = carbs_g - fiber_g. Energy uses USDA reported energy, not a new 4/4/9 calculation. This mixed dish has not been laboratory tested.","portion_basis":"Ingredient weights match the preparation named in each USDA reference. Cooked beans, rice, chicken and eggs are weighed after cooking. No additional sugar, oil, bread, sauces or garnishes are included. Final target yield is the sum of ingredient weights; replace evaporation with water after reheating. Cooking losses and ingredient variation are not modeled.","preparation":"Simmer the cooked lentils and spinach with tomato, onion, garlic, cumin and oil; add water as needed to restore the stated final portion mass.","ingredients":[{"fdc_id":172421,"grams":180,"description":"Lentils, mature seeds, cooked, boiled, without salt","per_100g":{"calories":116,"protein_g":9.02,"carbs_g":20.1,"fiber_g":7.9,"fat_g":0.38},"source_url":"https://fdc.nal.usda.gov/food-details/172421/nutrients"},{"fdc_id":168463,"grams":80,"description":"Spinach, cooked, boiled, drained, without salt","per_100g":{"calories":23,"protein_g":2.97,"carbs_g":3.75,"fiber_g":2.4,"fat_g":0.26},"source_url":"https://fdc.nal.usda.gov