-- Ten pairs = twenty rows. Pair 1 is the 15-minute post-meal walk.
-- The default planner chooses equipment-free, moderate activity. Descriptive
-- intensity is a template, not an assertion about an individual's capacity.
insert into public.workouts (
  id, title, environment, intensity, duration_mins, metabolic_benefit, swap_pair_id
) values
  ('20000000-0000-4000-8000-000000000001', 'Post-meal outdoor glucose walk', 'outdoor', 'low', 15, 'Gentle movement after a meal engages muscles and can support post-meal glucose management.', '20000000-0000-4000-8000-000000000002'),
  ('20000000-0000-4000-8000-000000000002', 'Post-meal indoor corridor walk', 'indoor', 'low', 15, 'Gentle movement after a meal engages muscles and can support post-meal glucose management.', '20000000-0000-4000-8000-000000000001'),
  ('20000000-0000-4000-8000-000000000003', 'Outdoor brisk walk', 'outdoor', 'moderate', 25, 'Sustained large-muscle movement supports cardiovascular fitness and glucose uptake.', '20000000-0000-4000-8000-000000000004'),
  ('20000000-0000-4000-8000-000000000004', 'Indoor low-impact marching', 'indoor', 'moderate', 25, 'Sustained large-muscle movement supports cardiovascular fitness and glucose uptake.', '20000000-0000-4000-8000-000000000003'),
  ('20000000-0000-4000-8000-000000000005', 'Park mobility flow', 'outdoor', 'low', 15, 'Gentle range-of-motion activity breaks up sedentary time.', '20000000-0000-4000-8000-000000000006'),
  ('20000000-0000-4000-8000-000000000006', 'Indoor standing mobility flow', 'indoor', 'low', 15, 'Gentle range-of-motion activity breaks up sedentary time.', '20000000-0000-4000-8000-000000000005'),
  ('20000000-0000-4000-8000-000000000007', 'Outdoor walk with easy intervals', 'outdoor', 'moderate', 20, 'Alternating comfortable and brisk movement supports aerobic conditioning.', '20000000-0000-4000-8000-000000000008'),
